/* Taşınmaz gösterme belgesi — dijital yer gösterme uygulamasıyla (dogusremax.github.io/matbuevraklar/yer-gosterme.html)
   BİREBİR aynı belge. Randevu sayfası müşteri imzaladığında PDF'i bu modülle tarayıcıda üretir.
   Tasarım, metin, logo ve broker imzası o uygulamadan kopyalandı; orada değişirse burada da değiştir.
   Kullanım: const b64 = await YerGostermeBelge.pdf({isim, tc, tel, email, evler:[{adres, fiyat, fiyatY}], danisman, tarih:"dd.MM.yyyy", imza:dataURL});
   html2canvas 1.4.1 ve jsPDF 2.5.1 sayfada yüklü olmalı. */
(function(){
const UMT_LOGO="data:image/png;base64,";
const BROKER_IMZA="data:image/png;base64,";
const YASAL=`Yukarıda adresi bulunan gayrimenkul, ##TARIH## tarihinde satın almak/kiralamak amacıyla ilk defa Müşteri'ye gösterilmiştir. RE/MAX Doğuş'un bilgisi olmaksızın söz konusu yerin 1 yıl içerisinde; Müşteri'nin kendisi, eşi, ortağı ve çalışanı bulunduğu şirket, şirket ortakları, şirketin ortak olduğu kuruluşlar ya da kan ve sıhri hısımları tarafından satın alındığı takdirde RE/MAX Doğuş gayrimenkulün satış bedelinin %4 + KDV'si; kiralandığı takdirde bir aylık kira bedeli + KDV'si tutarında hizmet bedeline hak kazanır. Müşteri bu maddede belirtilen şartı kabul ve taahhüt etmektedir. İşbu sözleşme 1 sayfadan oluşmaktadır ve 2 nüsha olarak düzenlenmiştir. Sözleşmeden doğan ihtilaflarda İstanbul Mahkeme ve İcra Daireleri yetkilidir.`;

const CSS=`.ygb-sheet table{width:100%;border-collapse:collapse;table-layout:fixed}
.ygb-sheet .hdr td{background:#21237B;padding:5px 10px;vertical-align:middle}
.ygb-sheet .fl{background:#DCE6F4;border:1px solid #BBB;padding:5px 10px;font-size:10pt}
.ygb-sheet .fv{background:#fff;border:1px solid #BBB;padding:5px 10px;font-size:10pt}
.ygb-sheet .shead{font-weight:700;font-size:10pt;margin:4mm 0 2px;padding:5px 10px}
.ygb-sheet .legal{font-size:9pt;line-height:1.5;margin-top:3mm;text-align:justify;cursor:pointer;border:1px dashed transparent;padding:4px;border-radius:4px;transition:border-color .2s}
.ygb-sheet .legal:hover{border-color:#fde68a;background:#fffbeb}
.ygb-sheet .sigBox{border:1.2px solid #21237B;background:#fff;padding:0;vertical-align:top}
.ygb-sheet .sh{background:#21237B;color:#fff;font-size:9pt;font-weight:700;text-align:center;padding:4px 6px;letter-spacing:.4px;text-transform:uppercase}
.ygb-sheet .sn{font-size:9pt;border-bottom:1px dotted #777;padding:3px 2px 4px;min-height:16px;line-height:1.3}
.ygb-sheet .sf{font-size:7.5pt;color:#595959;text-align:center;border-top:1px solid #ddd;padding-top:3px;font-weight:700;letter-spacing:.6px}`;
const fmtTL=v=>{const d=String(v||"").replace(/\D/g,"");return d?d.replace(/\B(?=(\d{3})+(?!\d))/g,".")+" TL":""};
const fmtTel=v=>{const d=String(v||"").replace(/\D/g,"").replace(/^90(?=5\d{9}$)/,"0").slice(0,11);if(!d)return"";let r=d[0]||"";if(d.length>1)r+=" ("+d.slice(1,4);if(d.length>=4)r+=") ";if(d.length>4)r+=d.slice(4,7);if(d.length>7)r+=" "+d.slice(7,9);if(d.length>9)r+=" "+d.slice(9,11);return r};
/* 4250000 → "Dört Milyon İki Yüz Elli Bin" (fiyat yazıyla boşsa) */
function yazi(n){n=parseInt(String(n||"").replace(/\D/g,""),10);if(!n)return"";
  const b=["","Bir","İki","Üç","Dört","Beş","Altı","Yedi","Sekiz","Dokuz"],o=["","On","Yirmi","Otuz","Kırk","Elli","Altmış","Yetmiş","Seksen","Doksan"];
  const uc=x=>{const y=Math.floor(x/100),on=Math.floor(x%100/10),bi=x%10;return[(y?(y>1?b[y]+" ":"")+"Yüz":""),o[on],b[bi]].filter(Boolean).join(" ");};
  const g=["","Bin","Milyon","Milyar"];let p=[],i=0;
  while(n>0){const x=n%1000;if(x){let t=uc(x);if(i===1&&x===1)t="";p.unshift([t,g[i]].filter(Boolean).join(" "));}n=Math.floor(n/1000);i++;}
  return p.join(" ")+" TL";}
const k=s=>String(s==null?"":s).replace(/[&<>"]/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c]));

function html(v){
  const evler=(v.evler||[]).filter(p=>p.adres);
  const fs=evler.length>1?"9pt":"10pt";
  let propRows="";
  evler.forEach((p,i)=>{
    const n=i+1;
    propRows+=`<tr><td class="fl" style="font-weight:700;width:34%;vertical-align:top">${n}) Gayrimenkul Adresi</td><td class="fv" colspan="3">${k(p.adres)}</td></tr>
    <tr><td class="fl" style="width:15%">Fiyatı</td><td class="fv">Rakam: ${k(fmtTL(p.fiyat))}</td><td class="fv" colspan="2">Yazı: ${k(p.fiyatY||yazi(p.fiyat))}</td></tr>`;
  });
  const bSig=`<img src="${BROKER_IMZA}" style="position:absolute;top:50%;left:50%;transform:translate(-50%,-50%);height:120%;z-index:2">`;
  return `<div class="ygb-sheet" style="font-size:${fs}">
    <table><tr class="hdr"><td style="color:#fff;font-size:11pt;font-weight:700;letter-spacing:1px;white-space:nowrap">RE/MAX DOĞUŞ</td><td style="text-align:right;color:#fff;font-weight:700;font-size:11pt;letter-spacing:.4px">TAŞINMAZ GÖSTERME BELGESİ</td></tr></table>
    <div style="text-align:right;font-size:${fs};font-weight:700;margin:4px 0 2px">TARİH: ${k(v.tarih)}</div>
    <div class="shead">Alıcı / Kiracı Adayı Bilgileri</div>
    <table>
      <tr><td class="fl" style="width:34%">Ad Soyad / Ticari Unvan</td><td class="fv">${k(v.isim)}</td></tr>
      <tr><td class="fl">TC Kimlik No / Vergi No – VD</td><td class="fv">${k(v.tc)}</td></tr>
      <tr><td class="fl">Telefon</td><td class="fv">${k(fmtTel(v.tel))}</td></tr>
      <tr><td class="fl">E-Posta</td><td class="fv">${k(v.email||"")}</td></tr>
    </table>
    <div class="shead">Görülen Gayrimenkul Aşağıdadır.</div>
    <table>${propRows}</table>
    <div class="legal">${k(YASAL.replaceAll("##TARIH##",v.tarih)).replace(/\n/g,"<br>")}</div>
    <table style="border-collapse:separate;border-spacing:3mm 2mm;margin-top:3mm"><tr>
      <td class="sigBox"><div class="sh">Gayrimenkulü Gören Kişi</div><div style="padding:4px 6px">
        <div class="sn">İsim/Soyisim: <b>${k(v.isim)}</b></div>
        <div class="sn">T.C. No: <b>${k(v.tc)}</b></div>
        <div style="height:22mm;position:relative;overflow:hidden;display:flex;align-items:center;justify-content:center">
          ${v.imza?`<img src="${v.imza}" style="max-height:50px;max-width:85%">`:""}
        </div>
        <div class="sf">İMZA</div></div></td>
      <td style="border:none;width:3mm"></td>
      <td class="sigBox"><div class="sh">RE/MAX DOĞUŞ</div><div style="padding:4px 6px">
        <div class="sn">Gayrimenkul Danışmanı</div>
        <div class="sn"><b>${k(v.danisman)}</b></div>
        <div style="height:22mm;position:relative;overflow:hidden;display:flex;align-items:center;justify-content:center">
          <img src="${UMT_LOGO}" style="height:20mm;opacity:.7">${bSig}
        </div>
        <div class="sf">İMZA</div></div></td>
    </tr></table>
  </div>`;
}

async function pdf(v){
  if(!document.getElementById("ygb-css")){const s=document.createElement("style");s.id="ygb-css";s.textContent=CSS;document.head.appendChild(s);}
  const w=document.createElement("div");
  w.innerHTML=html(v);
  const clone=w.firstElementChild;
  Object.assign(clone.style,{width:"210mm",minHeight:"auto",padding:"10mm",background:"#fff",position:"fixed",top:"0",left:"0",zIndex:"-9999",
    fontFamily:"'Times New Roman',Times,serif",color:"#1a1a1a",boxSizing:"border-box",lineHeight:"normal"});
  document.body.appendChild(clone);
  try{
    await new Promise(r=>setTimeout(r,500));
    const canvas=await html2canvas(clone,{scale:2,useCORS:true,allowTaint:true,backgroundColor:"#ffffff",logging:false,width:clone.scrollWidth,height:clone.scrollHeight});
    const {jsPDF}=window.jspdf;
    const doc=new jsPDF("p","mm","a4");
    const pageW=210,pageH=297,imgW=pageW,imgH=(canvas.height*imgW)/canvas.width;
    const img=canvas.toDataURL("image/jpeg",0.95);
    doc.addImage(img,"JPEG",0,0,imgW,Math.min(imgH,pageH));
    return doc.output("datauristring").split(",")[1];
  } finally { document.body.removeChild(clone); }
}
window.YerGostermeBelge={pdf,html};
})();
